import com.crowdin.client.core.http.impl.json.JacksonJsonTransformer;
import com.crowdin.client.projectsgroups.model.Project;
import com.crowdin.client.sourcefiles.model.FileInfo;
import com.crowdin.client.stringtranslations.model.LanguageTranslations;
import org.junit.Assert;
import org.junit.Test;
import java.util.Date;

public class JacksonJsonTransformerTest {


    @Test
    public void parseValidJsonTest() {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        String json = "{ \"name\": \"Test Project\", \"id\": 1, \"createdAt\": \"2022-02-15T09:40:26Z\" }";
        Project project = transformer.parse(json, Project.class);

        Assert.assertEquals("Test Project", project.getName());
        Assert.assertEquals(1, project.getId().intValue());
        Assert.assertNotNull(project.getCreatedAt());
    }

    @Test(expected = RuntimeException.class)
    public void parseInvalidJsonTest() {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        String json = "{ \"name\": \"Test Project\", \"id\": \"abc\", \"createdAt\": \"2022-02-15T09:40:26Z\" }";
        transformer.parse(json, Project.class);
    }

    @Test
    public void convertValidObjectTest() {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        FileInfo fileInfo = new FileInfo();
        fileInfo.setId(1L);
        fileInfo.setName("File 1");

        String json = transformer.convert(fileInfo);
        Assert.assertNotNull(json);
        Assert.assertTrue(json.contains("\"name\":\"File 1\""));
        Assert.assertTrue(json.contains("\"id\":1"));
    }

    @Test
    public void convertNullObjectTest() {
        JacksonJsonTransformer transformer = new JacksonJsonTransformer();
        String json = transformer.convert(null);
        Assert.assertEquals("null", json);
    }
}

